module reset_case(input logic clk, input logic d, output logic q);
  always_ff @(posedge clk) begin
    q <= d;
  end
endmodule

module dup_case(input logic clk, input logic a, output logic y);
  // TARGET_BLOCK
  always_ff @(posedge clk) begin
    y <= a;
  end
  // KEEP_BLOCK
  always_ff @(posedge clk) begin
    y <= a;
  end
endmodule

module min_case(input logic a, input logic b, output logic y);
  assign y = a & b;
endmodule

