module freq_divbyodd #(parameter int DIV = 5) (
  input logic clk,
  input logic rst_n,
  output logic clk_out
);
  logic [$clog2(DIV)-1:0] cnt;
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cnt <= '0;
      clk_out <= 1'b0;
    end else begin
      if (cnt == DIV-1) cnt <= '0;
      else cnt <= cnt + 1'b1;
      if (cnt == 0) clk_out <= ~clk_out;
    end
  end
endmodule

module radix2_div(
  input logic clk,
  input logic rst_n,
  input logic opn_valid,
  input logic op_signed,
  output logic done
);
  logic signed_mode;
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      signed_mode <= 1'b0;
      done <= 1'b0;
    end else begin
      if (opn_valid) begin
        signed_mode <= 1'b0;
      end
      done <= opn_valid;
    end
  end
endmodule

module microcode_ctrl(input logic clk, input logic rst_n, input logic [3:0] opcode, output logic [1:0] state);
  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] EXEC = 2'd1;
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE;
    else begin
      unique case (opcode)
        4'h1: state <= EXEC;
        default: state <= IDLE;
      endcase
    end
  end
endmodule

module amb_case(input logic a, input logic b, output logic y0, output logic y1);
  assign y0 = a & b;
  assign y1 = a & b;
endmodule

module ws_case(input logic a, input logic b, output logic y);
	assign y	=	a & b;
endmodule
